/// Events Group row iterator — empty on malformed dimensions.
#[derive(Debug, Clone)]
pub struct MdInstrumentDefinitionFxEventsGroupRows<'a> {
    data: &'a [u8],
    offset: usize,
    stride: usize,
    remaining: usize,
}

impl<'a> Iterator for MdInstrumentDefinitionFxEventsGroupRows<'a> {
    type Item = EventsGroup<'a>;

    fn next(&mut self) -> Option<EventsGroup<'a>> {
        if self.remaining == 0 {
            return None;
        }
        let data = self.data.get(self.offset..)?;
        self.offset = self.offset.checked_add(self.stride)?;
        self.remaining -= 1;
        EventsGroup::parse(data).ok()
    }
}

